// SPDX-License-Identifier: MIT
//! Mutation-audit tests (2026-11-27) for the code added since the 2026-11-17 card: line statements and custom
//! delimiters (lexer), `{% autoescape %}` regions, `super.super()`, `urlize`, `pprint`, `random`, `lipsum`, the `tojson`
//! string writer. Every expected string below was produced by the reference (Jinja2 3.1.6 / CPython 3.14 `pprint`),
//! never by this module.

const std = @import("std");
const testing = std.testing;
const jinja = @import("root.zig");

fn renderWith(gpa: std.mem.Allocator, opts: jinja.Options, src: []const u8, ctx: jinja.Value) ![]u8 {
    var env = try jinja.Environment.init(gpa, opts);
    defer env.deinit();
    return env.renderAlloc(gpa, src, ctx, null);
}

const Case = struct { tpl: []const u8, opts: jinja.Options = .{}, t: []const u8 = "", r: []const u8 = "", want: []const u8 };

fn runCases(cases: []const Case) !void {
    const gpa = testing.allocator;
    var failed: usize = 0;
    for (cases) |c| {
        var arena: std.heap.ArenaAllocator = .init(gpa);
        defer arena.deinit();
        const ctx = try jinja.valueFrom(arena.allocator(), .{ .t = c.t, .r = c.r });
        const out = renderWith(gpa, c.opts, c.tpl, ctx) catch |e| {
            std.debug.print("case failed with {s}: {s}\n", .{ @errorName(e), c.tpl });
            failed += 1;
            continue;
        };
        defer gpa.free(out);
        if (!std.mem.eql(u8, c.want, out)) {
            std.debug.print("case: {s}\n  want: {s}\n  got:  {s}\n", .{ c.tpl, c.want, out });
            failed += 1;
        }
    }
    try testing.expectEqual(@as(usize, 0), failed);
}

test "mutation 2026-11-27: line statements, line comments and custom delimiters (expected from Jinja2 3.1.6)" {
    try runCases(&.{
        .{ .tpl = "{{ 1 }} # x\n{{ 2 }}", .opts = .{ .line_statement_prefix = "#" }, .want = "1 # x\n2" },
        .{ .tpl = "# set a = 1\n# set b = 2\n{{ a }}{{ b }}", .opts = .{ .line_statement_prefix = "#" }, .want = "12" },
        .{ .tpl = "{% if 1 %}A{% endif %}\nz", .opts = .{ .line_statement_prefix = "{" }, .want = "A\nz" },
        .{ .tpl = "{{ 1 }}\nz", .opts = .{ .line_comment_prefix = "{" }, .want = "1\nz" },
        .{ .tpl = "a{{ 1 }}\nz", .opts = .{ .line_comment_prefix = "{{" }, .want = "a1\nz" },
        .{ .tpl = "{{ 1 }}\nz", .opts = .{ .line_statement_prefix = "{", .line_comment_prefix = "{{" }, .want = "1\nz" },
        .{ .tpl = "a\n\t# if 1\nb\n\t# endif\nc", .opts = .{ .line_statement_prefix = "#" }, .want = "a\nb\nc" },
        .{ .tpl = "a\n\x0b# if 1\nb\n\x0b# endif\nc", .opts = .{ .line_statement_prefix = "#" }, .want = "a\nb\nc" },
        .{ .tpl = "# set a = 1\n{{ a }}", .opts = .{ .line_statement_prefix = "#", .line_comment_prefix = "#" }, .want = "1" },
        .{ .tpl = "a\n  ## c\nb", .opts = .{ .line_statement_prefix = "#", .line_comment_prefix = "##" }, .want = "a\n\nb" },
        .{ .tpl = "a\t## c\nb", .opts = .{ .line_comment_prefix = "##" }, .want = "a\nb" },
        .{ .tpl = "a  \t ## c\nb", .opts = .{ .line_comment_prefix = "##" }, .want = "a\nb" },
        .{ .tpl = "%% for i in [1,2]\n{{ i }}\n%% endfor\n", .opts = .{ .line_statement_prefix = "%%" }, .want = "1\n2\n" },
        .{ .tpl = "x\n# for i in [1,2]\n[{{ i }}]\n# endfor\ny", .opts = .{ .line_statement_prefix = "#" }, .want = "x\n[1]\n[2]\ny" },
        .{ .tpl = "# for i in [1]:\n# if i == 2:\nno\n# elif i == 1:\nE\n# else:\nno\n# endif\n# endfor\n# macro m(x):\nM{{ x }}{{ caller() }}\n# endmacro\n# call m(5):\nC\n# endcall\n# block b:\nB\n# endblock\n# filter upper:\nabc\n# endfilter\n# autoescape true:\n{{ '<' }}\n# endautoescape\n", .opts = .{ .line_statement_prefix = "#" }, .want = "E\nM5C\n\nB\nABC\n&lt;\n" },
        .{ .tpl = "<%%% if 1 %%%>A<<< 'v' >>><!-- c -->B<%%% raw %%%><<< x >>> <%%% endraw %%%>C<%%%- if 1 -%%%> D <%%% endif %%%><%%% endif %%%>Z", .opts = .{ .delimiters = .{ .block_start = "<%%%", .block_end = "%%%>", .variable_start = "<<<", .variable_end = ">>>", .comment_start = "<!--", .comment_end = "-->" } }, .want = "AvB<<< x >>> CD Z" },
        .{ .tpl = "a <!--- c ---> b <!--+ c +--> c<<<- 1 ->>> <%%% raw %%%>x<%%% y <%%%- endraw -%%%>  e", .opts = .{ .delimiters = .{ .block_start = "<%%%", .block_end = "%%%>", .variable_start = "<<<", .variable_end = ">>>", .comment_start = "<!--", .comment_end = "-->" } }, .want = "ab  c1x<%%% ye" },
        .{ .tpl = "<%%% for i in [1, 2] %%%>[<<< i >>>]<%%% endfor %%%>", .opts = .{ .delimiters = .{ .block_start = "<%%%", .block_end = "%%%>", .variable_start = "<<<", .variable_end = ">>>", .comment_start = "<!--", .comment_end = "-->" } }, .want = "[1][2]" },
        .{ .tpl = "[[ 1 ]]{{ 2 }}", .opts = .{ .delimiters = .{ .variable_start = "[[", .variable_end = "]]" } }, .want = "1{{ 2 }}" },
        .{ .tpl = "<% if 1 %>a<% endif %>{% if 1 %}b{% endif %}", .opts = .{ .delimiters = .{ .block_start = "<%", .block_end = "%>" } }, .want = "a{% if 1 %}b{% endif %}" },
    });
}

test "mutation 2026-11-27: urlize (expected from Jinja2 3.1.6)" {
    try runCases(&.{
        .{ .tpl = "{{ t|urlize }}", .t = "http://a_b.com", .want = "<a href=\"http://a_b.com\" rel=\"noopener\">http://a_b.com</a>" },
        .{ .tpl = "{{ t|urlize }}", .t = "http://\xc3\x80.com", .want = "<a href=\"http://\xc3\x80.com\" rel=\"noopener\">http://\xc3\x80.com</a>" },
        .{ .tpl = "{{ t|urlize }}", .t = "http://a.com\thttp://b.com\rhttp://c.com\x1chttp://d.com\x1fhttp://e.com", .want = "<a href=\"http://a.com\" rel=\"noopener\">http://a.com</a>\t<a href=\"http://b.com\" rel=\"noopener\">http://b.com</a>\r<a href=\"http://c.com\" rel=\"noopener\">http://c.com</a>\x1c<a href=\"http://d.com\" rel=\"noopener\">http://d.com</a>\x1f<a href=\"http://e.com\" rel=\"noopener\">http://e.com</a>" },
        .{ .tpl = "{{ t|urlize }}", .t = "http://a%20b.com/x", .want = "<a href=\"http://a%20b.com/x\" rel=\"noopener\">http://a%20b.com/x</a>" },
        .{ .tpl = "{{ t|urlize }}", .t = "http://a.com:/x http://a.com:123456 http://a.com:65535/x http://a.com:12345", .want = "http://a.com:/x http://a.com:123456 <a href=\"http://a.com:65535/x\" rel=\"noopener\">http://a.com:65535/x</a> <a href=\"http://a.com:12345\" rel=\"noopener\">http://a.com:12345</a>" },
        .{ .tpl = "{{ t|urlize }}", .t = "http://a.com?q=1 http://a.com#f", .want = "<a href=\"http://a.com?q=1\" rel=\"noopener\">http://a.com?q=1</a> <a href=\"http://a.com#f\" rel=\"noopener\">http://a.com#f</a>" },
        .{ .tpl = "{{ t|urlize }}", .t = "http://a.bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb http://a.bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb", .want = "http://a.bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb <a href=\"http://a.bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb\" rel=\"noopener\">http://a.bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb</a>" },
        .{ .tpl = "{{ t|urlize }}", .t = "http://a.xn--a http://a.xn--bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb http://a.xn--bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb http://a.b1c2d3 http://a.xn--ab%c", .want = "http://a.xn--a http://a.xn--bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb <a href=\"http://a.xn--bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb\" rel=\"noopener\">http://a.xn--bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb</a> http://a.b1c2d3 <a href=\"http://a.xn--ab%c\" rel=\"noopener\">http://a.xn--ab%c</a>" },
        .{ .tpl = "{{ t|urlize }}", .t = "http://a..com", .want = "http://a..com" },
        .{ .tpl = "{{ t|urlize }}", .t = "ab.int ab.edu ab.gov ab.org ab.info ab.mil ab.com ab.net ab.xyz", .want = "<a href=\"https://ab.int\" rel=\"noopener\">ab.int</a> <a href=\"https://ab.edu\" rel=\"noopener\">ab.edu</a> <a href=\"https://ab.gov\" rel=\"noopener\">ab.gov</a> <a href=\"https://ab.org\" rel=\"noopener\">ab.org</a> <a href=\"https://ab.info\" rel=\"noopener\">ab.info</a> <a href=\"https://ab.mil\" rel=\"noopener\">ab.mil</a> <a href=\"https://ab.com\" rel=\"noopener\">ab.com</a> <a href=\"https://ab.net\" rel=\"noopener\">ab.net</a> ab.xyz" },
        .{ .tpl = "{{ t|urlize }}", .t = "ab.com:123456 ab.com:12345 com aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.com aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.com", .want = "ab.com:123456 <a href=\"https://ab.com:12345\" rel=\"noopener\">ab.com:12345</a> com aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.com <a href=\"https://aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.com\" rel=\"noopener\">aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.com</a>" },
        .{ .tpl = "{{ t|urlize }}", .t = "http://1234.1.1.1/ http://1..1.1/x http://1.2.3.4/ https://192.168.1.1/x https://[::1]/x", .want = "http://1234.1.1.1/ http://1..1.1/x <a href=\"http://1.2.3.4/\" rel=\"noopener\">http://1.2.3.4/</a> <a href=\"https://192.168.1.1/x\" rel=\"noopener\">https://192.168.1.1/x</a> <a href=\"https://[::1]/x\" rel=\"noopener\">https://[::1]/x</a>" },
        .{ .tpl = "{{ t|urlize }}", .t = "http://1.2.3.4:123456/x http://[::1]:123456/ http://[::111111111111111111111111]/ http://[::1111111111111111111111111]/", .want = "http://1.2.3.4:123456/x http://[::1]:123456/ <a href=\"http://[::111111111111111111111111]/\" rel=\"noopener\">http://[::111111111111111111111111]/</a> http://[::1111111111111111111111111]/" },
        .{ .tpl = "{{ t|urlize }}", .t = "mailto:@x.com mailto:ab.cd mailto:x@ x@ x@-a.com x@a.b.com x@a-b.com www.x@y.com @x@y.com a:b@c.com mailto:q@r.com", .want = "mailto:@x.com mailto:ab.cd mailto:x@ x@ x@-a.com <a href=\"mailto:x@a.b.com\">x@a.b.com</a> <a href=\"mailto:x@a-b.com\">x@a-b.com</a> www.x@y.com @x@y.com a:b@c.com <a href=\"mailto:q@r.com\">q@r.com</a>" },
        .{ .tpl = "{{ t|urlize }}", .t = "http://a.com/(x)y) (http://a.com/((x) www.example.org/some/long/path", .want = "<a href=\"http://a.com/(x)y\" rel=\"noopener\">http://a.com/(x)y</a>) (<a href=\"http://a.com/((x)\" rel=\"noopener\">http://a.com/((x)</a> <a href=\"https://www.example.org/some/long/path\" rel=\"noopener\">www.example.org/some/long/path</a>" },
        .{ .tpl = "{{ (t|safe)|urlize }}", .t = "<http://a.com> http://a.com/<b> (http://a.com/(x>) &lt;http://a.com&gt;", .want = "<<a href=\"http://a.com\" rel=\"noopener\">http://a.com</a>> <a href=\"http://a.com/<b>\" rel=\"noopener\">http://a.com/<b></a> (<a href=\"http://a.com/(x>)\" rel=\"noopener\">http://a.com/(x>)</a> &lt;<a href=\"http://a.com\" rel=\"noopener\">http://a.com</a>&gt;" },
        .{ .tpl = "{{ (t|safe)|urlize }}", .opts = .{ .autoescape = true }, .t = "a<b http://a.com/?x=<y>", .want = "a<b <a href=\"http://a.com/?x=<y>\" rel=\"noopener\">http://a.com/?x=<y></a>" },
        .{ .tpl = "{{ t|urlize }}", .opts = .{ .autoescape = true }, .t = "a<b http://a.com/?x=<y>", .want = "a&lt;b <a href=\"http://a.com/?x=&lt;y&gt;\" rel=\"noopener\">http://a.com/?x=&lt;y&gt;</a>" },
        .{ .tpl = "{% autoescape true %}{{ t|urlize }}{% endautoescape %}", .t = "a<b", .want = "a&lt;b" },
        .{ .tpl = "{{ missing|urlize }}|", .opts = .{ .undefined_policy = .lenient }, .want = "|" },
        .{ .tpl = "{{ t|urlize(none) }}", .t = "http://a.com/x", .r = "z\ta\nb\x0bc\x0cd\re  zz", .want = "<a href=\"http://a.com/x\" rel=\"noopener\">http://a.com/x</a>" },
        .{ .tpl = "{{ t|urlize(0) }}", .t = "http://a.com/x", .r = "z\ta\nb\x0bc\x0cd\re  zz", .want = "<a href=\"http://a.com/x\" rel=\"noopener\">...</a>" },
        .{ .tpl = "{{ t|urlize(12) }}", .t = "www.example.org/long/path http://a.com/\xc3\xa9\xc3\xa9\xc3\xa9\xc3\xa9\xc3\xa9\xc3\xa9\xc3\xa9\xc3\xa9", .r = "z\ta\nb\x0bc\x0cd\re  zz", .want = "<a href=\"https://www.example.org/long/path\" rel=\"noopener\">www.example....</a> <a href=\"http://a.com/\xc3\xa9\xc3\xa9\xc3\xa9\xc3\xa9\xc3\xa9\xc3\xa9\xc3\xa9\xc3\xa9\" rel=\"noopener\">http://a.com...</a>" },
        .{ .tpl = "{{ t|urlize(15) }}", .t = "http://a.com/\xc3\xa9\xc3\xa9\xc3\xa9\xc3\xa9\xc3\xa9\xc3\xa9\xc3\xa9\xc3\xa9", .r = "z\ta\nb\x0bc\x0cd\re  zz", .want = "<a href=\"http://a.com/\xc3\xa9\xc3\xa9\xc3\xa9\xc3\xa9\xc3\xa9\xc3\xa9\xc3\xa9\xc3\xa9\" rel=\"noopener\">http://a.com/\xc3\xa9\xc3\xa9...</a>" },
        .{ .tpl = "{{ t|urlize(20, false, none) }}", .t = "http://a.com/x", .r = "z\ta\nb\x0bc\x0cd\re  zz", .want = "<a href=\"http://a.com/x\" rel=\"noopener\">http://a.com/x</a>" },
        .{ .tpl = "{{ t|urlize(rel=none) }}", .t = "http://a.com/x", .r = "z\ta\nb\x0bc\x0cd\re  zz", .want = "<a href=\"http://a.com/x\" rel=\"noopener\">http://a.com/x</a>" },
        .{ .tpl = "{{ t|urlize(extra_schemes=none) }}", .t = "http://a.com/x", .r = "z\ta\nb\x0bc\x0cd\re  zz", .want = "<a href=\"http://a.com/x\" rel=\"noopener\">http://a.com/x</a>" },
        .{ .tpl = "{{ t|urlize(target='a\"b') }}", .t = "http://a.com/x", .r = "z\ta\nb\x0bc\x0cd\re  zz", .want = "<a href=\"http://a.com/x\" rel=\"noopener\" target=\"a&#34;b\">http://a.com/x</a>" },
        .{ .tpl = "{{ t|urlize(rel='a\"b') }}", .t = "http://a.com/x", .r = "z\ta\nb\x0bc\x0cd\re  zz", .want = "<a href=\"http://a.com/x\" rel=\"a&#34;b noopener\">http://a.com/x</a>" },
        .{ .tpl = "{{ t|urlize(rel='noopener nofollow', nofollow=true) }}", .t = "http://a.com/x", .r = "z\ta\nb\x0bc\x0cd\re  zz", .want = "<a href=\"http://a.com/x\" rel=\"nofollow noopener\">http://a.com/x</a>" },
        .{ .tpl = "{{ t|urlize(nofollow=true) }}", .t = "http://a.com/x", .r = "z\ta\nb\x0bc\x0cd\re  zz", .want = "<a href=\"http://a.com/x\" rel=\"nofollow noopener\">http://a.com/x</a>" },
        .{ .tpl = "{{ t|urlize(rel=r) }}", .t = "http://a.com/x", .r = "z\ta\nb\x0bc\x0cd\re  zz", .want = "<a href=\"http://a.com/x\" rel=\"a b c d e noopener z zz\">http://a.com/x</a>" },
        .{ .tpl = "{{ t|urlize(extra_schemes=['a_b.c+d-e:']) }}", .t = "a_b.c+d-e:x", .r = "z\ta\nb\x0bc\x0cd\re  zz", .want = "<a href=\"a_b.c+d-e:x\" rel=\"noopener\">a_b.c+d-e:x</a>" },
        .{ .tpl = "{{ t|urlize(10, false, '_blank', none, ['tel:']) }}", .t = "tel:12345678901234 tel:1 http://a.com/x", .r = "z\ta\nb\x0bc\x0cd\re  zz", .want = "<a href=\"tel:12345678901234\" rel=\"noopener\" target=\"_blank\">tel:12345678901234</a> <a href=\"tel:1\" rel=\"noopener\" target=\"_blank\">tel:1</a> <a href=\"http://a.com/x\" rel=\"noopener\" target=\"_blank\">http://a.c...</a>" },
        .{ .tpl = "{{ t|urlize(extra_schemes=['ab://']) }}", .t = "ab://x ab:// ab:/y", .r = "z\ta\nb\x0bc\x0cd\re  zz", .want = "<a href=\"ab://x\" rel=\"noopener\">ab://x</a> ab:// ab:/y" },
        .{ .tpl = "{{ (t|safe)|urlize }}", .t = "a<b", .r = "z\ta\nb\x0bc\x0cd\re  zz", .want = "a<b" },
        .{ .tpl = "{{ t|urlize(extra_schemes=['\xc3\xa91:']) }}", .t = "\xc3\xa91:x", .r = "z\ta\nb\x0bc\x0cd\re  zz", .want = "<a href=\"\xc3\xa91:x\" rel=\"noopener\">\xc3\xa91:x</a>" },
    });
}

test "mutation 2026-11-27: autoescape regions across macros, loops, includes and super() (expected from Jinja2 3.1.6)" {
    try runCases(&.{
        .{ .tpl = "{% autoescape true %}{% filter upper %}<i>{% endfilter %}{% endautoescape %}", .want = "<I>" },
        .{ .tpl = "{% autoescape true %}{{ (t|safe) ~ '<b>' }}{% endautoescape %}", .t = "<i>", .want = "<i>&lt;b&gt;" },
        .{ .tpl = "{% autoescape true %}{% for x in [1, 2] recursive %}<{{ x }}>{% if x == 1 %}{{ loop([2]) }}{% endif %}{% endfor %}{% endautoescape %}", .want = "<1><2><2>" },
        .{ .tpl = "{% autoescape true %}{{ (t|safe).replace('b', '<x>') }}{% endautoescape %}", .t = "<b>", .want = "<&lt;x&gt;>" },
        .{ .tpl = "{% autoescape true %}{{ (t|safe).lstrip() }}{% endautoescape %}", .t = "  <b>", .want = "<b>" },
        .{ .tpl = "{% autoescape true %}{% endautoescape %}{% macro m() %}{{ '<m>' }}{% endmacro %}{% autoescape true %}{{ m() }}{% endautoescape %}", .want = "<m>" },
        .{ .tpl = "{% macro m() %}{% autoescape true %}{{ caller() }}{% endautoescape %}{% endmacro %}{% call m() %}<q>{% endcall %}", .want = "<q>" },
        .{ .tpl = "{% macro m() %}{% autoescape caller() %}x{% endautoescape %}{% endmacro %}{% call m() %}1{% endcall %}", .want = "x" },
        .{ .tpl = "{{ ['<'] | pprint }}", .opts = .{ .autoescape = true }, .want = "[&#39;&lt;&#39;]" },
    });
}

